public class StrBuilder_indexOf_TriageGen1Test {

















    @Test
    public void testIndexOf_PartialMatchThenFail() {
        // Tests the 'continue outer' logic
        StrBuilder sb = new StrBuilder("ababcabc");
        // Searching for "abc"
        // At index 0: "aba" != "abc" -> continue outer
        // At index 2: "abc" == "abc" -> return 2
        assertEquals(2, sb.indexOf("abc", 0));
    }




}

