import static org.junit.Assert.*;

public class StrBuilder_indexOf_TriageGen1Test {



















    @Test
    public void testIndexOf_EdgeCaseLoopLimit() {
        // The loop condition is i < len where len = thisBuf.length - strLen
        // This tests the boundary of the loop
        StrBuilder sb = new StrBuilder("abc");
        // size is 3, strLen is 3, len = 3 - 3 = 0. Loop i < 0 won't execute.
        // However, the logic in the provided code uses thisBuf.length which might be > size.
        // But the initial check 'startIndex >= size' protects this.
        assertEquals(0, sb.indexOf("abc", 0));
    }


}

